#include <iostream>

int fibonacci(int n) {
  if (n <= 1) {
    return n;
  } else {
    return fibonacci(n - 1) + fibonacci(n - 2);
  }
}

int main() {
  int n;
  std::cout << "Enter the value of n: ";
  std::cin >> n;

  int fib_num = fibonacci(n);
  std::cout << "The " << n << "th Fibonacci number is: " << fib_num << std::endl;
  return 0;
}
